# Allow "star" singular but avoid matching "stars count of" first; capture "(N) stars?"
star_re = re.compile(r'([0-9,]+)\s*stars?(?!\s*count)')
def get_stars(t):
    if not isinstance(t, str): return None
    # try "stars count of N" first
    m2 = re.search(r'stars count of ([0-9,]+)', t)
    if m2:
        return int(m2.group(1).replace(',', ''))
    m = star_re.search(t)
    if m:
        return int(m.group(1).replace(',', ''))
    return None

pinfo['stars'] = pinfo['Project_Information'].apply(get_stars)
