def get_stars(t):
    if not isinstance(t, str): return None
    patterns = [
        r'stars count of ([0-9,]+)',
        r'star count of ([0-9,]+)',
        r'starred by ([0-9,]+)\s+users?',
        r'([0-9,]+)\s*stars?(?!\s*count)',
    ]
